style.css:
@-moz-document domain("youtube.com") {
/* === Pitch Black Background === */
  body, ytd-app, ytd-page-manager {
    background-color: #000000 !important;
    color: white !important;
  }

  /* === Hide Recommendations, Shorts, Comments, Subscriptions === */
  #related, 
  ytd-watch-next-secondary-results-renderer,
  ytd-rich-section-renderer, 
  #comments,
  ytd-guide-section-renderer:nth-child(2),
  ytd-mini-guide-entry-renderer[title="Subscriptions"],
  ytd-guide-entry-renderer[title="Trending"],
  ytd-guide-entry-renderer[title="Explore"],
  ytd-guide-entry-renderer[title="Gaming"] {
    display: none !important;
  }

  /* === Minimal Homepage (only Search Bar visible) === */
  ytd-rich-grid-renderer, 
  ytd-browse[page-subtype="home"] #contents ytd-rich-grid-renderer,
  ytd-rich-grid-media {
    display: none !important;
  }

  /* === Full Width Video Player === */
  #player-container, #primary-inner {
    max-width: 100% !important;
    width: 100% !important;
    margin: 0 auto !important;
  }

  /* === Hide Everything Except Video While Playing === */
  ytd-watch-flexy[theater] #secondary, 
  ytd-watch-flexy[theater] #below,
  ytd-watch-flexy[theater] #info,
  ytd-watch-flexy[theater] ytd-comments {
    display: none !important;
  }

  /* === Blur Background While Playing Video === */
  ytd-watch-flexy[theater] ytd-watch-next-secondary-results-renderer,
  ytd-watch-flexy[theater] #player-theater-container::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(10px);
    z-index: -1;
  }

  /* === Neon Red, Thin Progress Bar === */
  .ytp-progress-bar-container {
    height: 3px !important; /* thin line */
  }

  .ytp-scrubber-container {
    height: 3px !important; /* matching thin scrubber */
  }

  .ytp-progress-bar {
    background: black !important; /* background of progress bar */
  }

  .ytp-play-progress.ytp-swatch-background-color {
    background: #ff073a !important; /* neon red like Star Wars */
    box-shadow: 0 0 8px #ff073a, 0 0 12px #ff073a !important; /* neon glow */
  }

  .ytp-loaded-progress {
    background: #333 !important; /* subtle load background */
  }
}
